#!/usr/bin/env bash
# Launcher of the SRTM pre-impoundment bed run (plan docs/plans/2026-10-27-post2000-srtm-bed-plan.md): tiers by polygon
# area (km2), several processes per tier, then a single-process pass for memory retries; one BLAS thread per process.
# DO NOT EDIT THIS FILE WHILE IT IS RUNNING. Usage: bash 04_Code/scripts/srtm_bed_batch.sh
cd "$(dirname "$0")/../.." || exit 1
LOG=05_Results/by_date/2026-10-27/srtm_bed_v1/logs; mkdir -p "$LOG"
export PYTHONIOENCODING=utf-8 OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 MKL_NUM_THREADS=1
run() { .venv/Scripts/python.exe -I 04_Code/scripts/srtm_bed_v1.py "$@" 2>&1; }
tier() { size=$1; name=$2; n=$3; for i in $(seq 1 "$n"); do run run --size "$size" --part "$i/$n" >> "$LOG/${name}_${i}of${n}.log" & done; wait; }
tier 0:20 small 6
tier 20:200 mid 2
tier 200:1000000 large 1
run run >> "$LOG/retry.log"
echo "batch finished $(date -Iseconds)" >> "$LOG/batch.log"
